'use strict';

// MODULES //

var tape = require( 'tape' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var Float64Results = require( '@stdlib/ml/base/kmeans/results/float64' );
var res2str = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof res2str, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided a second argument which is not an object', function test( t ) {
	var results;
	var values;
	var i;

	results = new Float64Results();

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			res2str( results, value );
		};
	}
});

tape( 'the function throws an error if provided a `digits` option which is not a positive integer', function test( t ) {
	var results;
	var values;
	var i;

	results = new Float64Results();

	values = [
		'5',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			res2str( results, {
				'digits': value
			});
		};
	}
});

tape( 'the function serializes a results object to a string', function test( t ) {
	var expected;
	var actual;
	var value;

	value = new Float64Results();
	value.k = 4;
	value.samples = 10;
	value.features = 3;
	value.metric = 'sqeuclidean';
	value.algorithm = 'lloyd';
	value.replicates = 4;
	value.replicate = 2;
	value.iterations = 10;
	value.inertia = 3.28;

	actual = res2str( value );
	t.strictEqual( isString( actual ), true, 'returns expected value' );

	expected = [
		'',
		'K-means clustering using Lloyd algorithm',
		'',
		'    metric used: squared euclidean',
		'    total replicates: 4',
		'    best replicate: 2',
		'    total iterations: 10',
		'    inertia: 3.2800',
		'',
		'Clustering ran for 4 clusters and 10 data samples, each with 3 features'
	].join( '\n' );
	t.strictEqual( actual, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying the number of displayed digits (digits=2)', function test( t ) {
	var expected;
	var actual;
	var value;

	value = new Float64Results();
	value.k = 4;
	value.samples = 10;
	value.features = 3;
	value.metric = 'sqeuclidean';
	value.algorithm = 'lloyd';
	value.replicates = 4;
	value.replicate = 2;
	value.iterations = 10;
	value.inertia = 3.28;

	actual = res2str( value, {
		'digits': 2
	});
	t.strictEqual( isString( actual ), true, 'returns expected value' );

	expected = [
		'',
		'K-means clustering using Lloyd algorithm',
		'',
		'    metric used: squared euclidean',
		'    total replicates: 4',
		'    best replicate: 2',
		'    total iterations: 10',
		'    inertia: 3.28',
		'',
		'Clustering ran for 4 clusters and 10 data samples, each with 3 features'
	].join( '\n' );
	t.strictEqual( actual, expected, 'returns expected value' );

	t.end();
});
